corrected_code:
app.put('/api/users/:userId/payments/:paymentId', async (req, res) => {
  if (req.user.id !== req.params.userId) return res.status(403).send();
  const { paymentId, userId } = req.params;
  const updated = await Payment.update(req.body, {
    where: { id: paymentId, ownerId: userId }
  });
  res.json(updated);
});
